            next_c = (field_storage.INJ_CFG.rate.value & ~decoded_wr_biten[31:16]) | (decoded_wr_data[31:16] & decoded_wr_biten[31:16]);
            load_next_c = '1;
        end
        field_combo.INJ_CFG.rate.next = next_c;
        field_combo.INJ_CFG.rate.load_next = load_next_c;
    end
    always_ff @(posedge clk) begin
        if(rst) begin
            field_storage.INJ_CFG.rate.value <= 16'h0;
        end else begin
            if(field_combo.INJ_CFG.rate.load_next) begin
                field_storage.INJ_CFG.rate.value <= field_combo.INJ_CFG.rate.next;
            end
        end
    end
    assign hwif_out.INJ_CFG.rate.value = field_storage.INJ_CFG.rate.value;
    // Field: rs_loop_regs.INJ_SEED.value
    always_comb begin
        automatic logic [31:0] next_c;
        automatic logic load_next_c;
        next_c = field_storage.INJ_SEED.value.value;
        load_next_c = '0;
        if(decoded_reg_strb.INJ_SEED && decoded_req_is_wr) begin // SW write
            next_c = (field_storage.INJ_SEED.value.value & ~decoded_wr_biten[31:0]) | (decoded_wr_data[31:0] & decoded_wr_biten[31:0]);
            load_next_c = '1;
        end
        field_combo.INJ_SEED.value.next = next_c;
        field_combo.INJ_SEED.value.load_next = load_next_c;
    end
    always_ff @(posedge clk) begin
        if(rst) begin
            field_storage.INJ_SEED.value.value <= 32'hace1;
        end else begin
            if(field_combo.INJ_SEED.value.load_next) begin
                field_storage.INJ_SEED.value.value <= field_combo.INJ_SEED.value.next;
            end
        end
    end
    assign hwif_out.INJ_SEED.value.value = field_storage.INJ_SEED.value.value;

    //--------------------------------------------------------------------------
    // Write response
    //--------------------------------------------------------------------------
    assign cpuif_wr_ack = decoded_req & decoded_req_is_wr;
    // Writes are always granted with no error response
    assign cpuif_wr_err = '0;

    //--------------------------------------------------------------------------
    // Readback
    //--------------------------------------------------------------------------

    logic readback_err;
    logic readback_done;
    logic [31:0] readback_data;

    // Assign readback values to a flattened array
    logic [31:0] readback_array[32];
    assign readback_array[0][31:0] = (decoded_reg_strb.BUILD_ID && !decoded_req_is_wr) ? hwif_in.BUILD_ID.value.next : '0;
    assign readback_array[1][31:0] = (decoded_reg_strb.SCRATCH && !decoded_req_is_wr) ? field_storage.SCRATCH.value.value : '0;
    assign readback_array[2][2:0] = '0;
    assign readback_array[2][3:3] = (decoded_reg_strb.CTRL && !decoded_req_is_wr) ? field_storage.CTRL.bypass.value : '0;
    assign readback_array[2][4:4] = (decoded_reg_strb.CTRL && !decoded_req_is_wr) ? field_storage.CTRL.throttle_a.value : '0;
    assign readback_array[2][5:5] = (decoded_reg_strb.CTRL && !decoded_req_is_wr) ? field_storage.CTRL.throttle_b.value : '0;
    assign readback_array[2][6:6] = (decoded_reg_strb.CTRL && !decoded_req_is_wr) ? field_storage.CTRL.inj_seed_on_start.value : '0;
    assign readback_array[2][31:7] = '0;
    assign readback_array[3][15:0] = (decoded_reg_strb.GEN_BLOCKS && !decoded_req_is_wr) ? field_storage.GEN_BLOCKS.blocks.value : '0;
    assign readback_array[3][31:16] = '0;
    assign readback_array[4][31:0] = (decoded_reg_strb.GEN_SEED && !decoded_req_is_wr) ? field_storage.GEN_SEED.value.value : '0;
    assign readback_array[5][1:0] = (decoded_reg_strb.INJ_CFG && !decoded_req_is_wr) ? field_storage.INJ_CFG.mode.value : '0;
    assign readback_array[5][7:2] = '0;
    assign readback_array[5][15:8] = (decoded_reg_strb.INJ_CFG && !decoded_req_is_wr) ? field_storage.INJ_CFG.errors.value : '0;
    assign readback_array[5][31:16] = (decoded_reg_strb.INJ_CFG && !decoded_req_is_wr) ? field_storage.INJ_CFG.rate.value : '0;
    assign readback_array[6][31:0] = (decoded_reg_strb.INJ_SEED && !decoded_req_is_wr) ? field_storage.INJ_SEED.value.value : '0;
    assign readback_array[7][0:0] = (decoded_reg_strb.STATUS && !decoded_req_is_wr) ? hwif_in.STATUS.busy.next : '0;
    assign readback_array[7][1:1] = (decoded_reg_strb.STATUS && !decoded_req_is_wr) ? hwif_in.STATUS.gen_done.next : '0;
    assign readback_array[7][2:2] = (decoded_reg_strb.STATUS && !decoded_req_is_wr) ? hwif_in.STATUS.chk_a_done.next : '0;
    assign readback_array[7][3:3] = (decoded_reg_strb.STATUS && !decoded_req_is_wr) ? hwif_in.STATUS.chk_b_done.next : '0;
    assign readback_array[7][4:4] = (decoded_reg_strb.STATUS && !decoded_req_is_wr) ? hwif_in.STATUS.data_err_a.next : '0;
    assign readback_array[7][5:5] = (decoded_reg_strb.STATUS && !decoded_req_is_wr) ? hwif_in.STATUS.data_err_b.next : '0;
    assign readback_array[7][6:6] = (decoded_reg_strb.STATUS && !decoded_req_is_wr) ? hwif_in.STATUS.cmp_err.next : '0;
    assign readback_array[7][7:7] = (decoded_reg_strb.STATUS && !decoded_req_is_wr) ? hwif_in.STATUS.crc_a_ok.next : '0;
    assign readback_array[7][8:8] = (decoded_reg_strb.STATUS && !decoded_req_is_wr) ? hwif_in.STATUS.crc_b_ok.next : '0;
    assign readback_array[7][31:9] = '0;
    assign readback_array[8][15:0] = (decoded_reg_strb.PROFILE && !decoded_req_is_wr) ? hwif_in.PROFILE.n.next : '0;
    assign readback_array[8][23:16] = (decoded_reg_strb.PROFILE && !decoded_req_is_wr) ? hwif_in.PROFILE.t.next : '0;
    assign readback_array[8][27:24] = (decoded_reg_strb.PROFILE && !decoded_req_is_wr) ? hwif_in.PROFILE.m.next : '0;
    assign readback_array[8][31:28] = (decoded_reg_strb.PROFILE && !decoded_req_is_wr) ? hwif_in.PROFILE.spb.next : '0;
    assign readback_array[9][31:0] = (decoded_reg_strb.CRC_EXPECTED && !decoded_req_is_wr) ? hwif_in.CRC_EXPECTED.value.next : '0;
    assign readback_array[10][31:0] = (decoded_reg_strb.CRC_A && !decoded_req_is_wr) ? hwif_in.CRC_A.value.next : '0;
    assign readback_array[11][31:0] = (decoded_reg_strb.CRC_B && !decoded_req_is_wr) ? hwif_in.CRC_B.value.next : '0;
    assign readback_array[12][31:0] = (decoded_reg_strb.PKTS_A && !decoded_req_is_wr) ? hwif_in.PKTS_A.value.next : '0;
    assign readback_array[13][31:0] = (decoded_reg_strb.PKTS_B && !decoded_req_is_wr) ? hwif_in.PKTS_B.value.next : '0;
    assign readback_array[14][31:0] = (decoded_reg_strb.CYCLES && !decoded_req_is_wr) ? hwif_in.CYCLES.value.next : '0;
    assign readback_array[15][31:0] = (decoded_reg_strb.BLK_OK_A && !decoded_req_is_wr) ? hwif_in.BLK_OK_A.value.next : '0;
    assign readback_array[16][31:0] = (decoded_reg_strb.BLK_CORR_A && !decoded_req_is_wr) ? hwif_in.BLK_CORR_A.value.next : '0;
    assign readback_array[17][31:0] = (decoded_reg_strb.BLK_UNC_A && !decoded_req_is_wr) ? hwif_in.BLK_UNC_A.value.next : '0;
    assign readback_array[18][31:0] = (decoded_reg_strb.BLK_FRAME_A && !decoded_req_is_wr) ? hwif_in.BLK_FRAME_A.value.next : '0;
    assign readback_array[19][31:0] = (decoded_reg_strb.SYM_CORR_A && !decoded_req_is_wr) ? hwif_in.SYM_CORR_A.value.next : '0;
    assign readback_array[20][31:0] = (decoded_reg_strb.BLK_OK_B && !decoded_req_is_wr) ? hwif_in.BLK_OK_B.value.next : '0;
    assign readback_array[21][31:0] = (decoded_reg_strb.BLK_CORR_B && !decoded_req_is_wr) ? hwif_in.BLK_CORR_B.value.next : '0;
    assign readback_array[22][31:0] = (decoded_reg_strb.BLK_UNC_B && !decoded_req_is_wr) ? hwif_in.BLK_UNC_B.value.next : '0;
    assign readback_array[23][31:0] = (decoded_reg_strb.BLK_FRAME_B && !decoded_req_is_wr) ? hwif_in.BLK_FRAME_B.value.next : '0;
    assign readback_array[24][31:0] = (decoded_reg_strb.SYM_CORR_B && !decoded_req_is_wr) ? hwif_in.SYM_CORR_B.value.next : '0;
    assign readback_array[25][31:0] = (decoded_reg_strb.INJ_SYMBOLS && !decoded_req_is_wr) ? hwif_in.INJ_SYMBOLS.value.next : '0;
    assign readback_array[26][31:0] = (decoded_reg_strb.INJ_BLOCKS && !decoded_req_is_wr) ? hwif_in.INJ_BLOCKS.value.next : '0;
    assign readback_array[27][31:0] = (decoded_reg_strb.INJ_OVER_T && !decoded_req_is_wr) ? hwif_in.INJ_OVER_T.value.next : '0;
    assign readback_array[28][7:0] = (decoded_reg_strb.INJ_LAST && !decoded_req_is_wr) ? hwif_in.INJ_LAST.value.next : '0;
    assign readback_array[28][31:8] = '0;
    assign readback_array[29][31:0] = (decoded_reg_strb.CMP_DATA_MISMATCH && !decoded_req_is_wr) ? hwif_in.CMP_DATA_MISMATCH.value.next : '0;
    assign readback_array[30][31:0] = (decoded_reg_strb.CMP_STATUS_MISMATCH && !decoded_req_is_wr) ? hwif_in.CMP_STATUS_MISMATCH.value.next : '0;
    assign readback_array[31][31:0] = (decoded_reg_strb.CMP_BEATS && !decoded_req_is_wr) ? hwif_in.CMP_BEATS.value.next : '0;

    // Reduce the array
    always_comb begin
        automatic logic [31:0] readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr;
        readback_err = '0;
        readback_data_var = '0;
        for(int i=0; i<32; i++) readback_data_var |= readback_array[i];
        readback_data = readback_data_var;
    end

    assign cpuif_rd_ack = readback_done;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
